class TaskScheduler:
    def __init__(self):
        self.tasks = deque()

    def add_task(self, task):
        self.tasks.append(task)

    def process_next(self):
        if self.remaining() == 0:
            return None
        return self.tasks.popleft()

    def remaining(self):
        return len(self.tasks)

