from collections import deque

def sliding_window_max(nums, k):
    dq = deque()
    result = []
    for i, num in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

# Test
print(sliding_window_max([1, 3, -1, -3, 5, 3, 6, 7], 3))

from collections import deque

class PriorityPrinterQueue:
    def __init__(self):
        self.jobs = deque()

    def add_job(self, priority, job_name):
        new_job = (priority, job_name)
        inserted = False
        for i, existing in enumerate(self.jobs):
            if existing[0] < priority:
                self.jobs.insert(i, new_job)
                inserted = True
                break
        if not inserted:
            self.jobs.append(new_job)

    def next_job(self):
        if self.is_empty():
            return None
        return self.jobs.popleft()[1]

    def is_empty(self):
        return len(self.jobs) == 0

# Scenario
pq = PriorityPrinterQueue()
pq.add_job(2, 'report_A')
pq.add_job(1, 'urgent_memo')
pq.add_job(2, 'report_B')
print(pq.next_job())
print(pq.next_job())
print(pq.next_job())
